with flagged as (select *, case when lag(paid_at) over (partition by order_id order by paid_at, id) is null or paid_at > lag(paid_at) over (partition by order_id order by paid_at, id) + interval '60' day then 1 else 0 end as session_start_flag from payments) select *, sum(session_start_flag) over (partition by order_id order by paid_at, id rows between unbounded preceding and current row) as burst_id from flagged;
